function effect(s,e,scale=1){for(const [key,n] of Object.entries(e||{}))if(['health','joy','power','magic','wisdom','bond','fame'].includes(key)&&Number.isFinite(n))s[key]=bounded(s[key]+n*scale);}
function remember(s,text){const l=ensure(s);l.history.unshift({age:s.age,text});l.history.length=Math.min(20,l.history.length);}
function append(s,title,paragraphs,scene,kind='plan',tone){if(typeof Narrative==='undefined')return null;const entry=Narrative.append(s,{title,paragraphs,kind,scene,tone,key:'life-choice-'+quarter(s)+'-'+ensure(s).history.length,where:KINGDOMS[s.kingdom][0]});if(entry&&scene)entry.scene=scene;return entry;}
function planningAllowed(s){return !!s.accepted&&!s.dead;}
